const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (typeof $json.tender_id !== 'string' || !uuid.test($json.tender_id) || typeof $json.org_id !== 'string' || !uuid.test($json.org_id)) {
  throw new Error('INVALID_TENANT_CONTEXT');
}
return [{ json: $json }];

const tender = $('load-requirements').first().json;
const profile = $('load-company-profile').first().json || {};

// Build company profile object for LLM
const companyProfile = {
  name: profile.company_name || profile.name || 'Unbekanntes Unternehmen',
  capabilities_summary: profile.capabilities_summary || '',
  certifications: profile.certifications || [],
  trades: profile.trades || [],
  regions: profile.regions || [],
  service_types: profile.service_types || [],
  project_references: profile.project_references || [],
  // HQ address for distance calculation (IMP-03b)
  hq_street:      profile.hq_street      || null,
  hq_postal_code: profile.hq_postal_code || null,
  hq_city:        profile.hq_city        || null,
};

const requirements = tender.requirements || [];

// Bauort context for distance/travel risk assessment
const bauort = tender.region || null;

// Wertschöpfungsanalyse — from stage 2 classification
const vb = tender.value_breakdown || null;
const valueBreakdownNote = vb ? (function() {
  const s = vb.summary || {};
  const total = s.total || 1;
  const fremdPct = Math.round((s.fremd || 0) / total * 100);
  const lieferPct = Math.round((s.liefer || 0) / total * 100);
  const gemischtPct = Math.round((s.gemischt || 0) / total * 100);
  const eigenPct = 100 - fremdPct - lieferPct - gemischtPct;
  const parts = [];
  if (eigenPct > 0)    parts.push(eigenPct + '% Eigenleistung (' + s.eigen + ' Pos.)');
  if (fremdPct > 0)    parts.push(fremdPct + '% Fremdleistung (' + s.fremd + ' Pos.)');
  if (lieferPct > 0)   parts.push(lieferPct + '% Lieferleistung (' + s.liefer + ' Pos.)');
  if (gemischtPct > 0) parts.push(gemischtPct + '% Mischleistung (' + s.gemischt + ' Pos.)');
  return parts.join(', ');
})() : null;
const companyRegions = profile.regions || [];
// Simple heuristic: flag if Bauort is not within any of the company's listed regions
// e.g. company covers 'Bayern', Bauort is 'Nordrhein-Westfalen' → outside service area
const bauortOutsideRegions = bauort && companyRegions.length > 0
  ? !companyRegions.some(r => bauort.toLowerCase().includes(r.toLowerCase()) || r.toLowerCase().includes(bauort.toLowerCase()))
  : false;

return [{ json: {
  tender_id: tender.id,
  company_profile: companyProfile,
  requirements,
  requirements_json: JSON.stringify(requirements),
  bauort,
  bauort_outside_regions: bauortOutsideRegions,
  company_regions_str: companyRegions.join(', ') || 'nicht angegeben',
  value_breakdown_note: valueBreakdownNote,
} }];

// ─── Distance calculation node ───────────────────────────────────────────────
// Provider-agnostic distance calculation between company HQ and Bauort.
// To swap provider: replace the `geocode()` function body only.
// Current provider: Nominatim (OpenStreetMap) — free, no API key required.
//
// Returns distance_km (straight-line Haversine) + geocode metadata.
// Fails gracefully: if geocoding fails, distance_km = null and evaluation continues.

const ctx = $json;

// ─── Provider: Nominatim ─────────────────────────────────────────────────────
// To use OpenRouteService: replace URL + parse response accordingly.
// To use Google Maps: replace with Distance Matrix API call.
async function geocode(query) {
  const url = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' +
    encodeURIComponent(query);
  const resp = await fetch(url, {
    headers: { 'User-Agent': 'Tenderly/1.0 (tender-analysis)' },
    signal: AbortSignal.timeout(8000),
  });
  if (!resp.ok) throw new Error(`Nominatim HTTP ${resp.status}`);
  const data = await resp.json();
  if (!data || !data.length) return null;
  return { lat: parseFloat(data[0].lat), lon: parseFloat(data[0].lon), display: data[0].display_name };
}

// ─── Haversine formula ────────────────────────────────────────────────────────
// Straight-line distance in km. Accurate enough for go/no-go decisions.
// Typical road distance is ~1.2–1.4x straight-line for Central Europe.
function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat/2)**2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon/2)**2;
  return R * 2 * Math.asin(Math.sqrt(a));
}

// ─── Build geocode queries ────────────────────────────────────────────────────
const profile = ctx.company_profile || {};
const hqCity   = profile.hq_city        || null;
const hqPostal = profile.hq_postal_code || null;
const hqStreet = profile.hq_street      || null;
const bauort   = ctx.bauort             || null;

// Build address strings — as specific as available, Germany assumed
const hqQuery = hqPostal && hqCity
  ? `${hqPostal} ${hqCity}, Deutschland`
  : hqCity
  ? `${hqCity}, Deutschland`
  : hqStreet && hqCity
  ? `${hqStreet}, ${hqCity}, Deutschland`
  : null;

const bauortQuery = bauort ? `${bauort}, Deutschland` : null;

// ─── Geocode both and compute distance ───────────────────────────────────────
let distanceKm   = null;
let distanceNote = null;
let hqGeo        = null;
let bauortGeo    = null;

if (hqQuery && bauortQuery) {
  try {
    [hqGeo, bauortGeo] = await Promise.all([geocode(hqQuery), geocode(bauortQuery)]);
    if (hqGeo && bauortGeo) {
      distanceKm = Math.round(haversine(hqGeo.lat, hqGeo.lon, bauortGeo.lat, bauortGeo.lon));
      // Rough road-distance estimate (Haversine × 1.3 for Central Europe)
      const roadEstimate = Math.round(distanceKm * 1.3);
      distanceNote = `ca. ${distanceKm} km Luftlinie (ca. ${roadEstimate} km Fahrtstrecke geschätzt) von ${hqCity || 'Firmensitz'} nach ${bauort}`;
    } else {
      distanceNote = 'Geocodierung nicht erfolgreich — Entfernung unbekannt';
    }
  } catch (e) {
    distanceNote = 'Geocodierung fehlgeschlagen: ' + String(e).slice(0, 80);
  }
} else if (!hqQuery) {
  distanceNote = 'Firmenanschrift nicht hinterlegt — Entfernung nicht berechnet';
} else {
  distanceNote = 'Bauort unbekannt — Entfernung nicht berechnet';
}

return [{ json: {
  ...ctx,
  distance_km:    distanceKm,
  distance_note:  distanceNote,
  hq_geo:         hqGeo,
  bauort_geo:     bauortGeo,
}}];

const tender = $('load-requirements').first().json;
const tenderId = tender.id;
const evaluationKeys = ['strategic_fit_score', 'bid_recommendation', 'rationale', 'strengths', 'eligibility_summary', 'eligibility_requirements', 'risks', 'clarifications'];
const summaryKeys = ['compliant_count', 'partial_count', 'not_met_count', 'blocking_issues'];
const eligibilityKeys = ['id', 'status', 'is_blocking'];
const riskKeys = ['id', 'title', 'text', 'severity', 'mitigation'];
const clarificationKeys = ['id', 'question', 'priority'];
const coverageKeys = ['source_insufficient', 'source_truncated', 'source_char_count', 'extracted_char_count', 'source_char_limit', 'requirement_count', 'requirement_limit', 'requirement_limit_reached'];
const isBoundedString = (value, maxLength) =>
  typeof value === 'string' && value.trim().length > 0 && value.length <= maxLength;
const isExactObject = (value, keys) =>
  value !== null && typeof value === 'object' && !Array.isArray(value) &&
  Object.keys(value).length === keys.length && keys.every((key) => Object.prototype.hasOwnProperty.call(value, key));
const isNonnegativeInteger = (value) => Number.isInteger(value) && value >= 0;
const parseIfString = (value) => typeof value === 'string' ? JSON.parse(value) : value;
const hasUniqueIds = (items) => new Set(items.map((item) => item.id)).size === items.length;

let evaluation;
try {
  const content = $json.choices?.[0]?.message?.content;
  evaluation = typeof content === 'string'
    ? JSON.parse(content.replace(/```json|```/g, '').trim())
    : content;
  if (!isExactObject(evaluation, evaluationKeys)) throw new Error('invalid response');

  // Gemini (json_object mode) sometimes returns nested collections as JSON-encoded
  // strings; normalize before validating so jsonb columns still store arrays/objects.
  for (const key of ['risks', 'clarifications', 'eligibility_requirements', 'eligibility_summary', 'strengths']) {
    evaluation[key] = parseIfString(evaluation[key]);
  }

  if (
    !Number.isInteger(evaluation.strategic_fit_score) ||
    evaluation.strategic_fit_score < 0 ||
    evaluation.strategic_fit_score > 100 ||
    !['recommend_bid', 'needs_review', 'recommend_no_bid'].includes(evaluation.bid_recommendation) ||
    !isBoundedString(evaluation.rationale, 5000) ||
    !Array.isArray(evaluation.strengths) ||
    evaluation.strengths.length > 20 ||
    !evaluation.strengths.every((strength) => isBoundedString(strength, 500)) ||
    !isExactObject(evaluation.eligibility_summary, summaryKeys) ||
    !summaryKeys.every((key) => isNonnegativeInteger(evaluation.eligibility_summary[key])) ||
    !Array.isArray(evaluation.eligibility_requirements) ||
    evaluation.eligibility_requirements.length > 25 ||
    !Array.isArray(evaluation.risks) ||
    evaluation.risks.length < 3 ||
    evaluation.risks.length > 8 ||
    !Array.isArray(evaluation.clarifications) ||
    evaluation.clarifications.length < 3 ||
    evaluation.clarifications.length > 8
  ) throw new Error('invalid response');

  const sourceRequirements = Array.isArray(tender.requirements) ? tender.requirements : [];
  const knownRequirementIds = new Set(
    sourceRequirements
      .map((requirement) => requirement?.id)
      .filter((id) => isBoundedString(id, 100))
  );
  if (evaluation.eligibility_requirements.length !== knownRequirementIds.size) {
    throw new Error('invalid response');
  }
  for (const requirement of evaluation.eligibility_requirements) {
    if (
      !isExactObject(requirement, eligibilityKeys) ||
      !isBoundedString(requirement.id, 100) ||
      !['compliant', 'partial', 'not_met'].includes(requirement.status) ||
      typeof requirement.is_blocking !== 'boolean' ||
      !knownRequirementIds.has(requirement.id)
    ) throw new Error('invalid response');
  }
  if (!hasUniqueIds(evaluation.eligibility_requirements)) throw new Error('invalid response');

  for (const risk of evaluation.risks) {
    if (
      !isExactObject(risk, riskKeys) ||
      !isBoundedString(risk.id, 100) ||
      !isBoundedString(risk.title, 60) ||
      !isBoundedString(risk.text, 2000) ||
      !['low', 'medium', 'high'].includes(risk.severity) ||
      !isBoundedString(risk.mitigation, 2000)
    ) throw new Error('invalid response');
  }
  if (!hasUniqueIds(evaluation.risks)) throw new Error('invalid response');

  for (const clarification of evaluation.clarifications) {
    if (
      !isExactObject(clarification, clarificationKeys) ||
      !isBoundedString(clarification.id, 100) ||
      !isBoundedString(clarification.question, 2000) ||
      !['medium', 'high'].includes(clarification.priority)
    ) throw new Error('invalid response');
  }
  if (!hasUniqueIds(evaluation.clarifications)) throw new Error('invalid response');

  const actualCounts = { compliant: 0, partial: 0, not_met: 0, blocking: 0 };
  for (const requirement of evaluation.eligibility_requirements) {
    actualCounts[requirement.status]++;
    if (requirement.is_blocking) actualCounts.blocking++;
  }
  if (
    evaluation.eligibility_summary.compliant_count !== actualCounts.compliant ||
    evaluation.eligibility_summary.partial_count !== actualCounts.partial ||
    evaluation.eligibility_summary.not_met_count !== actualCounts.not_met ||
    evaluation.eligibility_summary.blocking_issues !== actualCounts.blocking
  ) throw new Error('invalid response');

  const sourceById = new Map(sourceRequirements.map((requirement) => [requirement?.id, requirement]));
  let unresolvedCritical = knownRequirementIds.size === 0;
  for (const requirement of evaluation.eligibility_requirements) {
    const source = sourceById.get(requirement.id);
    if (source?.is_critical === true && requirement.status === 'partial') unresolvedCritical = true;
    if (source?.is_critical === true && requirement.status === 'not_met' && !requirement.is_blocking) {
      throw new Error('invalid response');
    }
  }
  const expectedRecommendation = actualCounts.blocking > 0
    ? 'recommend_no_bid'
    : unresolvedCritical
      ? 'needs_review'
      : evaluation.strategic_fit_score >= 70
        ? 'recommend_bid'
        : evaluation.strategic_fit_score >= 50 ? 'needs_review' : 'recommend_no_bid';
  if (evaluation.bid_recommendation !== expectedRecommendation) {
    throw new Error('invalid response');
  }
} catch {
  console.error('LLM_RESPONSE_INVALID_JSON');
  throw new Error('LLM_RESPONSE_INVALID_JSON');
}

// Coverage is workflow-owned metadata. Apply its conservative override only after
// the raw model score/recommendation pair has passed every validation above.
const coverage = tender.requirements_coverage;
const coverageIsValid =
  isExactObject(coverage, coverageKeys) &&
  typeof coverage.source_insufficient === 'boolean' &&
  typeof coverage.source_truncated === 'boolean' &&
  isNonnegativeInteger(coverage.source_char_count) &&
  isNonnegativeInteger(coverage.extracted_char_count) &&
  coverage.source_char_limit === 12000 &&
  coverage.extracted_char_count === Math.min(coverage.source_char_count, coverage.source_char_limit) &&
  coverage.source_truncated === (coverage.source_char_count > coverage.source_char_limit) &&
  isNonnegativeInteger(coverage.requirement_count) &&
  coverage.requirement_count === (Array.isArray(tender.requirements) ? tender.requirements.length : 0) &&
  coverage.requirement_limit === 25 &&
  typeof coverage.requirement_limit_reached === 'boolean' &&
  coverage.requirement_limit_reached === (coverage.requirement_count === coverage.requirement_limit);
const finalBidRecommendation = coverageIsValid &&
  !coverage.source_insufficient &&
  !coverage.source_truncated &&
  !coverage.requirement_limit_reached
    ? evaluation.bid_recommendation
    : 'needs_review';

// Forward distance data from geocode-distance node
const distance_km   = $('geocode-distance').first().json.distance_km   ?? null;
const distance_note = $('geocode-distance').first().json.distance_note ?? null;

return [{ json: {
  id: tenderId,
  strategic_fit_score: evaluation.strategic_fit_score,
  bid_recommendation: finalBidRecommendation,
  rationale: evaluation.rationale,
  strengths: evaluation.strengths,
  eligibility_summary: evaluation.eligibility_summary,
  eligibility_requirements: evaluation.eligibility_requirements,
  risks: evaluation.risks,
  clarifications: evaluation.clarifications,
  processing_status: 'complete',
  distance_km,
  distance_note,
} }];

const eval_data = $('parse-evaluation').first().json;
return [{ json: {
  id: eval_data.id,
  strategic_fit_score: eval_data.strategic_fit_score,
  bid_recommendation: eval_data.bid_recommendation,
  rationale: eval_data.rationale || '',
  strengths: eval_data.strengths || [],
  eligibility_summary: eval_data.eligibility_summary,
  eligibility_requirements: eval_data.eligibility_requirements || [],
  risks: eval_data.risks || [],
  clarifications: eval_data.clarifications || [],
  processing_status: 'complete'
} }];
